const attachments = $input.all().map(item => ({
  name: item.json.name || 'Attachment',
  url: item.json.webViewLink || ''
}));

return [{
  json: {
    ...$input.first().json,
    attachmentsArray: attachments
  }
}];

const results = [];

for (const item of $input.all()) {
  const binaryKeys = Object.keys(item.binary || {});
  for (const key of binaryKeys) {
    results.push({
      json: {
        ...item.json,
        attachmentKey: key,
        fileName: item.binary[key].fileName
      },
      binary: {
        data: item.binary[key]
      }
    });
  }
}

return results;

